/* core stats v1.0 (master: kor-app src/core/stats.js). Shared by PhasaKAO and JeyCampus (PhasaLAO keeps its own, RYU 2026-11-28,
   so its sheet's columns stay as they are). Edit only this master, raise the version, then run  node tools/core-copy.js ../kor-app-en.
   Three parts: ST = anonymous usage events sent to the app's Google Sheet, STP = the public 학습 통계 page, SV = the short survey.
   What is sent (rows [time, event, code, a, b] and the batch fields id, v, dev, os, pwa, lang) must not change: the sheet's
   Apps Script (tools/stats/Code.gs) reads them by position.
   Per-app values from window.APPCFG.stats (src/app-config.js): url (empty = nothing recorded), key (storage prefix, e.g. kolearn-lo),
   openCode() (what goes in the code column of "open"), AC (menu colours), langs (names of explanation languages, or none),
   img {done, head} (survey pictures, or none), t (all words shown on the page and survey).
   build.js shows the 학습 통계 page only when app-config.js has  statsPublic: true. */
var STATS_C = (window.APPCFG && window.APPCFG.stats) || {}, STATS_T = STATS_C.t || {};
